# The data URIs the page's <img> reads, built once at import.
_DATA_URIS = {style: "data:image/png;base64," + text for style, text in _PNG_BASE64.items()}


def data_uri(style):
    """The data URI of `style`'s picture, data:image/png;base64,...; a name not in STYLES is refused."""
    if style not in _DATA_URIS:
        raise ValueError(f"no sponsored QR style named {style!r}")
    return _DATA_URIS[style]
